def mark_outside(grid):
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    boundary = 5

    # Start from all grid edge cells that are not boundary
    for r in range(rows):
        for c in [0, cols-1]:
            if grid[r][c] != boundary and not visited[r][c]:
                stack = [(r, c)]
                visited[r][c] = True
                while stack:
                    rr, cc = stack.pop()
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = rr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc]:
                            if grid[nr][nc] != boundary:
                                visited[nr][nc] = True
                                stack.append((nr, nc))

    for c in range(cols):
        for r in [0, rows-1]:
            if r not in [0, rows-1] and c not in [0, cols-1]:
                pass  # already handled
        if grid[0][c] != boundary and not visited[0][c]:
            stack = [(0, c)]
            visited[0][c] = True
            while stack:
                rr, cc = stack.pop()
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = rr+dr, cc+dc
                    if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc]:
                        if grid[nr][nc] != boundary:
                            visited[nr][nc] = True
                            stack.append((nr, nc))
        if grid[rows-1][c] != boundary and not visited[rows-1][c]:
            stack = [(rows-1, c)]
            visited[rows-1][c] = True
            while stack:
                rr, cc = stack.pop()
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = rr+dr, cc+dc
                    if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc]:
                        if grid[nr][nc] != boundary:
                            visited[nr][nc] = True
                            stack.append((nr, nc))

    return visited

